    ('047b3724-6a72-5a29-91f1-24f6750dfbf5'::uuid, 'Quiz — Des solides, des patrons et des litres', 'Maths', '6e', 'Voir dans l’espace et calculer des volumes', 'd1a71cde-8788-5dd5-845b-d823493d00a1'::uuid),
    ('871bb1a6-ec94-5ed9-974d-28d0b3b30b82'::uuid, 'Quiz — Quand tout augmente dans le même rapport', 'Maths', '6e', 'Proportionnalité', 'a46446d3-936a-54be-8a3a-c0fd654b5987'::uuid),
    ('56931cc4-b54f-5490-a895-8c3a62c5c4d0'::uuid, 'Quiz — Recueillir, représenter, résumer', 'Maths', '6e', 'Statistiques', 'a9634e2f-7146-577a-952a-672d6257fd0e'::uuid),
    ('0e31b54c-5968-5f1d-a035-60a6d6eb185a'::uuid, 'Quiz — Mesurer la chance', 'Maths', '6e', 'Probabilités', '5189484f-a8f9-5a54-a60b-48c2d2ac8a9c'::uuid),
    ('0cb5a637-af6b-53c9-97a2-f1a2d3507b30'::uuid, 'Quiz — Donner des instructions à une machine', 'Maths', '6e', 'Initiation à la pensée informatique', '6085e190-136e-5a28-87cf-c15a64abd7d5'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('ac2dee11-0ad9-598d-9c9e-dba5a5247eb5'::uuid, 'eb68a2ef-a237-55bb-bc8f-4ddfa812798a'::uuid, 'Dans 246,305, que vaut le chiffre 3 ?', 'mcq', '["3 dixièmes","3 centièmes","3 unités","3 millièmes"]'::jsonb, 0, 'Il occupe le premier rang après la virgule.', 1),
    ('5e1474ba-a560-5b39-b2be-ec78619a03dd'::uuid, 'eb68a2ef-a237-55bb-bc8f-4ddfa812798a'::uuid, 'Quelle est l’écriture fractionnaire de 3,25 ?', 'mcq', '["325/100","325/10","3,25/100","25/100"]'::jsonb, 0, 'Deux chiffres après la virgule, deux zéros au dénominateur.', 2),
    ('6fccf0ea-cd34-5c78-815a-f80f2935b03c'::uuid, 'eb68a2ef-a237-55bb-bc8f-4ddfa812798a'::uuid, 'Quel nombre est le plus grand ?', 'mcq', '["12,7","12,25","12,199","12,0999"]'::jsonb, 0, '7 dixièmes valent plus que 2 dixièmes.', 3),
    ('6dc8ebf1-808a-5be7-ba4c-186f1fa08f45'::uuid, 'eb68a2ef-a237-55bb-bc8f-4ddfa812798a'::uuid, 'Que vaut 3,47 arrondi au dixième ?', 'mcq', '["3,5","3,4","3,47","4"]'::jsonb, 0, 'Le chiffre suivant vaut 7, donc on arrondit au supérieur.', 4),
    ('d303bc15-2c11-57b5-825e-b57248d15cbc'::uuid, 'eb68a2ef-a237-55bb-bc8f-4ddfa812798a'::uuid, 'Entre quels entiers consécutifs se situe 3,7 ?', 'mcq', '["Entre 3 et 4","Entre 2 et 3","Entre 3,5 et 4,5","Entre 0 et 3"]'::jsonb, 0, 'C’est un encadrement à l’unité.', 5),
    ('0226cfd3-74cc-5a96-8565-35294569b5dd'::uuid, 'eb68a2ef-a237-55bb-bc8f-4ddfa812798a'::uuid, 'Dans 246, quel est le nombre de dizaines ?', 'mcq', '["24","4","46","240"]'::jsonb, 0, 'Le chiffre des dizaines est 4, le nombre de dizaines est 24.', 6),
    ('4f5cf9b9-c4a2-5c42-81a4-ee263e2d1d1a'::uuid, 'eb68a2ef-a237-55bb-bc8f-4ddfa812798a'::uuid, 'Comment appelle-t-on le nombre associé à un point d’une demi-droite graduée ?', 'mcq', '["Son abscisse","Son ordonnée","Sa position","Sa graduation"]'::jsonb, 0, 'Chaque nombre a un point unique.', 7),
